class Solution:
    def numberOfWays(self, numPeople: int) -> int:
        MOD = 1_000_000_007
        dp = [0] * (numPeople + 1)
        dp[0] = 1

        for people in range(2, numPeople + 1, 2):
            for partner in range(1, people, 2):
                left = partner - 1
                right = people - partner - 1
                dp[people] = (dp[people] + dp[left] * dp[right]) % MOD

        return dp[numPeople]

